struct Config {
    unsigned int is_ready : 1;
    unsigned int error_level : 3; // Max 7
    unsigned int setting_mode : 4;
    int temperature : 8;        // Signed field
    unsigned int : 0;           // Forces next field to boundary
    unsigned int unique_id : 16;
};

struct Config status;

status.is_ready = 1;
status.error_level = 5;

// Memory usage is optimized by packing:
// sizeof(struct Config) is typically 8 bytes (64 bits)
// instead of 4 * sizeof(int)
// Note: Packing order is implementation dependent.
